SELECT r.name, COUNT(*) FROM orders o JOIN customer_addresses a ON a.address_id = o.address_id JOIN cities ci ON ci.city_id = a.city_id JOIN regions r ON r.region_id = ci.region_id WHERE NOT o.is_deleted AND o.status NOT IN ('cancelled', 'canceled', 'payment_failed') AND CAST(o.order_at AS DATE) BETWEEN DATE '2025-03-01' AND DATE '2025-03-31' AND r.name IN ('Dhaka', 'Chattogram') GROUP BY 1
